from ...base.client import BaseClient
from typing import TypedDict, Unpack


class SearchChatThreadsKwargs(TypedDict):
    after: str
    before: str


class SearchMethods(BaseClient):
    """
    Методы группы 'Поиск' из https://im-docs.corp.mail.ru/
    """

    async def rapi_search(
        self,
        keyword: str,
        withoutBlocked: bool = False,
        withoutBots: bool = False,
    ) -> dict:
        """
        Поиск
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/search",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "keyword": keyword,
                    "withoutBlocked": withoutBlocked,
                    "withoutBots": withoutBots,
                },
            },
        )

    async def rapi_searchThreadsFeed(self, keyword: str, pagesize: int = 50):
        """
        Поиск по потоку тредов
        """
        return await self.post(
            "rapi/searchThreadsFeed",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "pagesize": pagesize,
                    "filter": {"keyword": keyword},
                },
            },
        )

    async def rapi_searchChatThreads(
        self, sn: str, keyword: str, author: str, pagesize: int = 50, **kwargs: Unpack[SearchChatThreadsKwargs]
    ) -> dict:
        r"""
        Ппоиск по сообщениям среди тредов указанного чата
        По самому чату поиск не осуществляется.
        :param sn: id чата для поиска
        :param pagesize: количество совпадений в выдаче
        :param keyword: текст для поиска
        :param author: screenname автора искомого сообщения (experimental)
        param after: дата в формате dd.mm.yyyy \n
        param before: дата в формате dd.mm.yyyy \n
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/searchChatThreads",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "pagesize": pagesize,
                    "filter": {
                        "keyword": keyword,
                        "author": author,
                        "data": {**kwargs},
                    },
                    "sn": sn,
                },
            },
        )

    async def rapi_searchAllDialogs(self, filter_keyword: str, mentions_resolve: bool = True) -> dict:
        """
        Поиск по всем диалогам
        """
        return await self.post(
            "rapi/searchAllDialogs",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "filter": {"keyword": filter_keyword},
                    "mentions": {"resolve": mentions_resolve},
                },
            },
        )

    async def rapi_searchOneDialog(self, chatId: str, filter_keyword: str, mentions_resolve: bool = True) -> dict:
        """
        Поиск по определенному чату/треду
        """
        return await self.post(
            "rapi/searchOneDialog",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "filter": {"keyword": filter_keyword},
                    "mentions": {"resolve": mentions_resolve},
                    "pagesize": 50,
                    "sn": chatId,
                },
            },
        )
